{"command": "cd /tmp/sv-bafdbc5da7a745a8a7291f791e4570bd/advanced-multi-complexity && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            tfm = fw['framework']
            for pkg in fw['topLevelPackages']:
                key = (name, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    proj, tfm, pkg = key
    bv = b.get(key)
    av = a.get(key)
    if bv != av:
        changes.append((proj, tfm, pkg, bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((proj, tfm, pkg, av))

if changes:
    print('CHANGES:')
    print(f'{\"Project\":<18} {\"TFM\":<8} {\"Package\":<45} {\"Before\":<12} {\"After\":<12}')
    for c in changes:
        print(f'{c[0]:<18} {c[1]:<8} {c[2]:<45} {c[3]:<12} {c[4]:<12}')
else:
    print('No changes detected.')

print()
print(f'Unchanged: {len(unchanged)} package-project-tfm combinations')
